# owner: platform
"""Weekly timesheet rows, one line of text per worker."""

from typing import Dict, Iterable, List

from hourglass.models import Shift


def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts to total")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("shift has a blank worker")


def _tally(shifts: List[Shift]) -> Dict[str, List[int]]:
    """Map worker to [shift count, total minutes]."""
    totals: Dict[str, List[int]] = {}
    for shift in shifts:
        entry = totals.setdefault(shift.worker, [0, 0])
        entry[0] += 1
        entry[1] += shift.span.minutes
    return totals


def _format_row(name: str, entry: List[int]) -> str:
    count, mins = entry
    return f"{name}: {count} shifts, {mins / 60:.1f} hours"


def _rank(item) -> tuple:
    return (-item[1][1], item[0])


# ---
def timesheet_rows(shifts: Iterable[Shift]) -> List[str]:
    """Lines of name, shifts and hours, busiest first."""
    shifts = list(shifts)
    _check(shifts)
    totals = _tally(shifts)
    order = sorted(totals.items(), key=_rank)
    return [_format_row(*item) for item in order]

after.tests/test_timesheet.py:
# owner: platform
import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_rows


def make_shift(worker, start, end, day="mon"):
    return Shift(worker, day, Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        rows = timesheet_rows([
            make_shift("Ana", 480, 540),
            make_shift("Brisa", 480, 720),
            make_shift("Ana", 480, 600, "tue")
        ])
        self.assertEqual(
            rows,
            ["Brisa: 1 shifts, 4.0 hours",
             "Ana: 2 shifts, 3.0 hours"]
        )

    def test_one_decimal(self):
        rows = timesheet_rows([make_shift("Ana", 0, 20)])
        self.assertEqual(rows, ["Ana: 1 shifts, 0.3 hours"])

    def test_tie_breaks_by_name(self):
        rows = timesheet_rows([
            make_shift("Zed", 0, 60),
            make_shift("Amy", 0, 60)
        ])
        self.assertTrue(rows[0].startswith("Amy"))

    def test_empty(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_rows([make_shift("  ", 0, 60)])
